function renderRepHotelBody(){const el=document.getElementById('rep33HotelBody'),sel=document.getElementById('rep33Hotel');if(!el||!sel)return;const h=sel.value,r=repLatestByHotel().find(x=>x.hotel===h)?.r;if(!r){el.innerHTML='';return;}const depts=(r.departments||[]).filter(x=>norm(x.name)!=='GRI');const neg=(r.negCategories||[]).slice(0,6),pos=(r.posCategories||[]).slice(0,6);el.innerHTML=`<div class="od-kpis compact"><article><span>GRI</span><strong>${fmt(r.kpis?.gri,1)}%</strong><small>${signed(r.kpis?.griDelta,' p.p.')}</small></article><article><span>Reviews</span><strong>${fmt(r.kpis?.reviews,0)}</strong><small>${signed(r.kpis?.reviewsDelta,'')}</small></article><article><span>Resposta</span><strong>${fmt(r.kpis?.mgmtResp,1)}%</strong><small>${signed(r.kpis?.mgmtRespDelta,' p.p.')}</small></article><article><span>CQI</span><strong>${fmt(r.competition?.cqi,1)}</strong><small>Compset ${fmt(r.competition?.compsetGri,1)}</small></article></div><div class="od-grid2"><div><h4>Departamentos</h4>${depts.map(d=>bar(d.name,num(d.gri)||0,100,num(d.gri)>=90?'good':num(d.gri)>=80?'warn':'bad',`${fmt(d.gri,1)}%`)).join('')}</div><div><h4>Concorrência</h4>${(r.competition?.ranking||[]).slice(0,6).map(x=>`<div class="od-rankline"><span>${x.rank}. ${esc(x.name)}</span><b>${fmt(x.gri,1)}%</b></div>`).join('')||'<p class="muted">Sem compset.</p>'}</div></div><div class="od-grid2"><div><h4>Pontos de atenção</h4>${neg.map(x=>`<span class="od-tag bad">${esc(x.category)} · ${fmt(x.count,0)}</span>`).join('')||'—'}</div><div><h4>Pontos fortes</h4>${pos.map(x=>`<span class="od-tag good">${esc(x.category)} · ${fmt(x.count,0)}</span>`).join('')||'—'}</div></div>`;}

// ---------- Reputação semestral — port nativo da ferramenta semestral V3 ----------
const SEM_ROLES={panel:'Painel',results:'Resultados',competition:'Concorrência',responses:'Respostas',semantic:'Semântica',mentions:'Menções'};
function semClean(v){return String(v??'').replace(/\u00a0/g,' ').replace(/\s+/g,' ').trim();}
function semNorm(v){return semClean(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function semNum(v){if(v===null||v===undefined||v===''||v==='-')return null;if(typeof v==='number')return Number.isFinite(v)?v:null;let s=String(v).replace('%','').replace('+','').replace(',','.').trim(),n=Number(s);return Number.isFinite(n)?n:null;}
function semFindHeader(rows,terms,start=0){const tt=terms.map(semNorm);return (rows||[]).findIndex((r,i)=>i>=start&&tt.every(t=>(r||[]).some(c=>semNorm(c)===t)));}
function semHeaderMap(row){const m={};(row||[]).forEach((v,i)=>{if(semClean(v))m[semNorm(v)]=i;});return m;}
function semFirst(row,keys,map){for(const k of keys){const i=map[semNorm(k)];if(i!==undefined)return row?.[i];}return null;}
function semIsHotel(v){const n=semNorm(v);return n.startsWith('vila gale')||n.startsWith('vg ')||!!HOTEL_ALIASES[norm(v)];}
function semDateMeta(book){const texts=[];for(const rows of Object.values(book?.sheets||{}))for(const r of (rows||[]).slice(0,8))for(const c of (r||[]).slice(0,4))if(typeof c==='string')texts.push(semClean(c));const text=texts.find(x=>/date range/i.test(x))||texts.join(' ');const mm=[...text.matchAll(/(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(\d{4})/gi)];const mons={jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,oct:10,nov:11,dec:12};const iso=m=>m?`${m[3]}-${String(mons[m[2].toLowerCase()]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`:null;const start=iso(mm[0]),end=iso(mm[1]),id=start&&end?`${start}_${end}`:'semester_'+Date.now();return{id,start,end,label:start?`${Number(start.slice(5,7))<=6?'1.º':'2.º'} Semestre ${start.slice(0,4)}`:'Semestre importado',range:start&&end?`${start} a ${end}`:'Período não identificado'};}
function semDetectRole(name,book){const names=Object.keys(book?.sheets||{}),first=semClean(book?.sheets?.[names[0]]?.[0]?.[0]),blob=semNorm(name+' '+names.join(' ')+' '+first);if(names.includes('Mentions')||blob.includes('todas as mencoes'))return'mentions';if(names.includes('Indexes Evolution')&&names.includes('My Establishments'))return'panel';if(first.startsWith('Reviews / Competition')||blob.includes('concorrencia'))return'competition';if(first.startsWith('Reviews Management Responses')||blob.includes('management response')||blob.includes('gerenciamento de respostas'))return'responses';if(first.startsWith('Semantic / Results')||blob.includes('semantica resultados'))return'semantic';if(first.startsWith('Reviews / Results')||blob.includes('avaliacoes resultados'))return'results';return null;}
function semWeighted(rows,key,wkey){let sw=0,sv=0;for(const r of rows||[]){const v=semNum(r?.[key]),w=semNum(r?.[wkey]);if(Number.isFinite(v)&&Number.isFinite(w)&&w>0){sv+=v*w;sw+=w;}}return sw?sv/sw:null;}
function semSum(rows,key){return (rows||[]).reduce((a,r)=>a+(Number.isFinite(semNum(r?.[key]))?Number(r[key]):0),0);}
function semParseHotelSummary(files){const rows=files.results?.sheets?.Summary||[],hi=semFindHeader(rows,['Hotel','Index','Reviews']);if(hi<0)return[];const out=[];for(const r of rows.slice(hi+1)){const hv=semClean(r?.[1]);if(!semIsHotel(hv))continue;out.push({hotel:canonHotel(hv),gri:semNum(r[2]),change:semNum(r[3]),reviews:semNum(r[4])||0,reviewsChange:semNum(r[5]),semantic:semNum(r[6]),semanticChange:semNum(r[7]),goal:semNum(r[8])});}return out.filter(x=>isCurrentHotel(x.hotel)&&allowedHotel(x.hotel));}
function semParseSemanticSummary(files){const rows=files.semantic?.sheets?.Summary||[],hi=semFindHeader(rows,['Product','Mentions','Positive (%)']);if(hi<0)return[];const h=semHeaderMap(rows[hi]);return rows.slice(hi+1).filter(r=>semIsHotel(semFirst(r,['Product'],h))).map(r=>({hotel:canonHotel(semFirst(r,['Product'],h)),mentions:semNum(semFirst(r,['Mentions'],h))||0,mentionsChange:semNum(semFirst(r,['Mentions change'],h)),positiveVolume:semNum(semFirst(r,['Positive Volume'],h))||0,positive:semNum(semFirst(r,['Positive (%)'],h)),positiveChange:semNum(semFirst(r,['Positive change'],h)),negativeVolume:semNum(semFirst(r,['Negative Volume'],h))||0,negative:semNum(semFirst(r,['Negative (%)'],h))})).filter(x=>isCurrentHotel(x.hotel)&&allowedHotel(x.hotel));}
function semParseResponses(files){const rows=files.responses?.sheets?.Summary||[],hi=semFindHeader(rows,['Hotel','Response Ratio','Avg. Time (days)']);if(hi<0)return[];return rows.slice(hi+1).filter(r=>semIsHotel(r?.[1])).map(r=>({hotel:canonHotel(r[1]),responded:semNum(r[3])||0,respondable:semNum(r[4])||0,responseRatio:semNum(r[5]),responseChange:semNum(r[6]),avgDays:semNum(r[8]),daysChange:semNum(r[9])})).filter(x=>isCurrentHotel(x.hotel)&&allowedHotel(x.hotel));}
function semParseCompetition(files){const rows=files.competition?.sheets?.Index||[],hi=semFindHeader(rows,['Hotel','GRI™','Compset','CQI™']);if(hi<0)return[];return rows.slice(hi+1).filter(r=>semIsHotel(r?.[1])).map(r=>({hotel:canonHotel(r[1]),gri:semNum(r[2]),griChange:semNum(r[3]),compset:semNum(r[4]),compsetChange:semNum(r[5]),compRank:semClean(r[6]),compReviews:semNum(r[7])||0,cqi:semNum(r[12]),cqiChange:semNum(r[13])})).filter(x=>isCurrentHotel(x.hotel)&&allowedHotel(x.hotel));}
function semParseDepartments(files){const rows=files.results?.sheets?.Departments||[],hi=semFindHeader(rows,['Hotel','Department','Index']);if(hi<0)return[];return rows.slice(hi+1).filter(r=>semIsHotel(r?.[1])&&semClean(r?.[2])).map(r=>({hotel:canonHotel(r[1]),department:semClean(r[2]),index:semNum(r[3]),change:semNum(r[4]),reviews:semNum(r[5])||0,reviewsChange:semNum(r[6]),semantic:semNum(r[7]),semanticChange:semNum(r[8])})).filter(x=>isCurrentHotel(x.hotel)&&allowedHotel(x.hotel)&&semNorm(x.department)!=='gri');}
function semParseResultSources(files){const rows=files.results?.sheets?.Sources||[],hi=semFindHeader(rows,['Hotel','Source','Index']);if(hi<0)return[];const h=semHeaderMap(rows[hi]);return rows.slice(hi+1).map(r=>({hotel:canonHotel(semFirst(r,['Hotel'],h)),source:semClean(semFirst(r,['Source'],h)),index:semNum(semFirst(r,['Index'],h)),change:semNum(semFirst(r,['Change'],h)),reviews:semNum(semFirst(r,['Reviews'],h))||0,positive:semNum(semFirst(r,['Positive (%)'],h)),neutral:semNum(semFirst(r,['Neutral (%)'],h)),negative:semNum(semFirst(r,['Negative (%)'],h)),semantic:semNum(semFirst(r,['Mentions (%)'],h))})).filter(x=>x.source&&semNorm(x.source)!=='gri'&&isCurrentHotel(x.hotel)&&allowedHotel(x.hotel));}
function semParseResponseSources(files){const rows=files.responses?.sheets?.['By Hotels']||[],hi=semFindHeader(rows,['Hotel','Source','Response Ratio']);if(hi<0)return[];const h=semHeaderMap(rows[hi]);return rows.slice(hi+1).map(r=>({hotel:canonHotel(semFirst(r,['Hotel'],h)),source:semClean(semFirst(r,['Source'],h)),responded:semNum(semFirst(r,['Responded'],h))||0,respondable:semNum(semFirst(r,['Respondable'],h))||0,ratio:semNum(semFirst(r,['Response Ratio'],h)),change:semNum(semFirst(r,['Change'],h)),avgDays:semNum(semFirst(r,['Avg. Time (days)'],h))})).filter(x=>x.source&&semNorm(x.source)!=='all sources'&&isCurrentHotel(x.hotel)&&allowedHotel(x.hotel));}
function semParseDimension(files,sheetName){const rows=files.semantic?.sheets?.[sheetName]||[];if(!rows.length)return[];const dimension=sheetName==='Trip Type'?'Trip Type':sheetName==='Countries-Areas'?'Countries-Areas':sheetName,detailTitle=semNorm(dimension+' - Details by Establishment'),detailIdx=rows.findIndex(r=>semNorm(r?.[0])===detailTitle);let hi=semFindHeader(rows,['Product',dimension,'Mentions'],detailIdx>0?detailIdx:0);if(hi<0)return[];const h=semHeaderMap(rows[hi]);return rows.slice(hi+1).map(r=>({hotel:canonHotel(semFirst(r,['Product'],h)),name:semClean(semFirst(r,[dimension],h)),mentions:semNum(semFirst(r,['Mentions'],h))||0,mentionsChange:semNum(semFirst(r,['Mentions change'],h)),positiveVolume:semNum(semFirst(r,['Positive Volume'],h))||0,positive:semNum(semFirst(r,['Positive (%)'],h)),positiveChange:semNum(semFirst(r,['Positive change'],h)),negativeVolume:semNum(semFirst(r,['Negative Volume'],h))||0,negative:semNum(semFirst(r,['Negative (%)'],h))})).filter(x=>x.name&&!/^all /i.test(x.name)&&isCurrentHotel(x.hotel)&&allowedHotel(x.hotel));}
function semParseDaily(files){const rows=files.panel?.sheets?.['Indexes Evolution']||[],hi=semFindHeader(rows,['Date','GRI™','Reviews']);if(hi<0)return[];const h=semHeaderMap(rows[hi]);return rows.slice(hi+1).map(r=>({date:semFirst(r,['Date'],h),gri:semNum(semFirst(r,['GRI™'],h)),reviews:semNum(semFirst(r,['Reviews'],h))||0,mentions:semNum(semFirst(r,['Mentions'],h))||0})).filter(x=>x.gri!=null);}
function semParseMentions(files){const rows=files.mentions?.sheets?.Mentions||[],hi=semFindHeader(rows,['Establishment','Mention','Sentiment','Category']);if(hi<0)return[];const h=semHeaderMap(rows[hi]);return rows.slice(hi+1).map(r=>({date:semClean(semFirst(r,['Date'],h)),hotel:canonHotel(semFirst(r,['Establishment'],h)),reviewer:semClean(semFirst(r,['Reviewer'],h)),country:semClean(semFirst(r,['Country'],h)),language:semClean(semFirst(r,['Language'],h)),source:semClean(semFirst(r,['Source'],h)),mention:semClean(semFirst(r,['Mention'],h)),sentiment:semClean(semFirst(r,['Sentiment'],h)),keyword:semClean(semFirst(r,['Keyword'],h)),concept:semClean(semFirst(r,['Concept'],h)),subconcept:semClean(semFirst(r,['Subconcept'],h)),category:semClean(semFirst(r,['Category'],h)),rating:semClean(semFirst(r,['Review Rating'],h)),review:semClean(semFirst(r,['Review text'],h))})).filter(x=>x.hotel&&isCurrentHotel(x.hotel)&&allowedHotel(x.hotel));}
function semBuildPeriod(meta,files,fileMeta){const hs=semParseHotelSummary(files),sm=semParseSemanticSummary(files),rr=semParseResponses(files),cc=semParseCompetition(files);const hotels=hs.map(h=>Object.assign({},h,sm.find(x=>x.hotel===h.hotel)||{},rr.find(x=>x.hotel===h.hotel)||{},cc.find(x=>x.hotel===h.hotel)||{}));return{...meta,files:fileMeta,hotels,departments:semParseDepartments(files),sources:semParseResultSources(files),responseSources:semParseResponseSources(files),semantic:{categories:semParseDimension(files,'Categories'),sources:semParseDimension(files,'Sources'),languages:semParseDimension(files,'Languages'),countries:semParseDimension(files,'Countries-Areas'),tripTypes:semParseDimension(files,'Trip Type')},daily:semParseDaily(files),mentions:semParseMentions(files),loadedAt:new Date().toISOString()};}
function semMigrate(){const s=state.semester||{};if(!Array.isArray(s.periods))s.periods=[];if(!s.subtab)s.subtab='overview';if(!s.dimension)s.dimension='categories';if(!s.region)s.region='Todas';if(!s.hotel)s.hotel='Todas';if(!s.selectedId&&s.periods[0])s.selectedId=s.periods[0].id;state.semester=s;}
function semCurrent(){semMigrate();return state.semester.periods.find(x=>x.id===state.semester.selectedId)||state.semester.periods[0]||null;}
function semScopeHotels(p){let a=(p?.hotels||[]).filter(x=>isCurrentHotel(x.hotel)&&allowedHotel(x.hotel));if(state.semester.hotel!=='Todas')a=a.filter(x=>x.hotel===state.semester.hotel);else if(state.semester.region!=='Todas')a=a.filter(x=>hotelRegion(x.hotel)===state.semester.region);return a;}
